result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/rope/__init__.py", "content": """"A balanced rope for efficient editing of very large strings.

The tree is an AVL-balanced binary tree whose leaves hold string fragments
of at most ``LEAF_MAX`` (64) characters.  ``insert`` and ``delete`` run in
O(log n) plus the size of the edited fragment -- the full string is never
rebuilt.  Balance is maintained structurally by AVL rotations inside
``_concat``, so the depth of a rope with n characters never exceeds
~1.44 * log2(n / LEAF_MAX) + O(1): depth is always bounded logarithmically
relative to the payload, which is the "rebalance when too deep" guarantee.
"""

from __future__ import annotations

from collections import deque

LEAF_MAX = 64

__all__ = ["Rope", "LEAF_MAX"]


class _Node:
    __slots__ = ("text", "left", "right", "length", "height")

    def __init__(self, text=None, left=None, right=None):
        if left is None and right is None:
            # Leaf node.  Invariant: len(text) <= LEAF_MAX (empty allowed).
            self.text = text
            self.left = None
            self.right = None
            self.length = len(text)
            self.height = 0
        else:
            # Internal node.
            self.text = None
            self.left = left
            self.right = right
            self.length = left.length + right.length
            self.height = 1 + max(left.height, right.height)


def _leaf(s: str) -> _Node:
    return _Node(text=s)


def _branch(l: _Node | None, r: _Node | None) -> _Node | None:
    """Combine two subtrees, merging tiny adjacent leaves opportunistically."""
    if l is None:
        return r
    if r is None:
        return l
    if (
        l.text is not None
        and r.text is not None
        and l.length + r.length <= LEAF_MAX
    ):
        return _leaf(l.text + r.text)
    return _Node(left=l, right=r)


def _height(t: _Node | None) -> int:
    return -1 if t is None else t.height


def _balance(l: _Node | None, r: _Node | None) -> _Node | None:
    """Join two AVL trees whose heights differ by at most 2 into an AVL tree.

    Uses single/double AVL rotations as needed; purely functional (builds new
    nodes along the joined root only).
    """
    joined = _branch(l, r)
    if joined is None or abs(_height(l) - _height(r)) <= 1:
        return joined
    if _height(l) > _height(r):
        # Left side too tall.
        if _height(l.left) >= _height(l.right):
            # Single right rotation.
            return _branch(l.left, _branch(l.right, r))
        # Double rotation (left-right).
        lr = l.right
        return _branch(_branch(l.left, lr.left), _branch(lr.right, r))
    else:
        # Right side too tall.
        if _height(r.right) >= _height(r.left):
            # Single left rotation.
            return _branch(_branch(l, r.left), r.right)
        # Double rotation (right-left).
        rl = r.left
        return _branch(_branch(l, rl.left), _branch(rl.right, r))


def _concat(a: _Node | None, b: _Node | None) -> _Node | None:
    """Concatenate two AVL ropes in O(|h(a) - h(b)| + 1)."""
    if a is None:
        return b
    if b is None:
        return a
    d = b.height - a.height
    if -1 <= d <= 1:
        return _branch(a, b)
    if d < -1:  # a taller by >= 2: graft b into a's right spine
        return _balance(a.left, _concat(a.right, b))
    else:       # b taller by >= 2: graft a into b's left spine
        return _balance(_concat(a, b.left), b.right)


def _split(t: _Node | None, i: int) -> tuple[_Node | None, _Node | None]:
    """Split t into (t[:i], t[i:]) in O(depth); both results are AVL ropes."""
    if t is None or i <= 0:
        return None, t
    if i >= t.length:
        return t, None
    if t.text is not None:
        return _leaf(t.text[:i]), _leaf(t.text[i:])
    if i <= t.left.length:
        ll, lr = _split(t.left, i)
        return ll, _concat(lr, t.right)
    rl, rr = _split(t.right, i - t.left.length)
    return _concat(t.left, rl), rr


def _build(s: str) -> _Node | None:
    """Build a balanced rope over s bottom-up from 64-char leaves."""
    if not s:
        return None
    queue = deque(_leaf(s[i : i + LEAF_MAX]) for i in range(0, len(s), LEAF_MAX))
    while len(queue) > 1:
        a = queue.popleft()
        b = queue.popleft() if queue else None
        queue.append(_branch(a, b))
    return queue[0]


class Rope:
    """Mutable balanced rope supporting O(log n)-ish insert/delete."""

    __slots__ = ("_root",)

    def __init__(self, s: str = ""):
        self._root = _build(s)

    # -- constructors ------------------------------------------------------

    @classmethod
    def from_str(cls, s: str) -> "Rope":
        return cls(s)

    # -- basic accessors ----------------------------------------------------

    def __len__(self) -> int:
        return self._root.length if self._root is not None else 0

    def index(self, i: int) -> str:
        """Return the character at position i."""
        n = len(self)
        if not 0 <= i < n:
            raise IndexError(f"index {i} out of range for rope of length {n}")
        t = self._root
        while t.text is None:
            if i < t.left.length:
                t = t.left
            else:
                i -= t.left.length
                t = t.right
        return t.text[i]

    def slice(self, i: int, j: int) -> str:
        """Return self[i:j] as a plain string (indices clamped like Python)."""
        n = len(self)
        i = max(0, min(i, n))
        j = max(i, min(j, n))
        parts: list[str] = []
        _collect(self._root, i, j, parts)
        return "".join(parts)

    def __str__(self) -> str:
        parts: list[str] = []
        _collect(self._root, 0, len(self), parts)
        return "".join(parts)

    def __getitem__(self, key):
        if isinstance(key, slice):
            start, stop, step = key.indices(len(self))
            if step == 1:
                return self.slice(start, stop)
            return str(self)[key]
        if isinstance(key, int):
            return self.index(key if key >= 0 else key + len(self))
        raise TypeError(f"invalid key: {key!r}")

    def __repr__(self) -> str:
        return f"Rope({str(self)!r})"

    def __eq__(self, other) -> bool:
        if isinstance(other, Rope):
            return str(self) == str(other)
        if isinstance(other, str):
            return str(self) == other
        return NotImplemented

    # -- editing -------------------------------------------------------------
    # Both operations split around the edit range (O(log n)), build a small
    # balanced tree for any newly inserted text, and re-concatenate with AVL
    # joins (O(log n)).  The untouched bulk of the string is never copied.

    def insert(self, i: int, s: str) -> "Rope":
        """Insert s at position i (clamped to [0, len]); returns self."""
        if not s:
            return self
        l, r = _split(self._root, _clamp(i, len(self)))
        self._root = _concat(_concat(l, _build(s)), r)
        return self

    def delete(self, i: int, j: int) -> "Rope":
        """Delete self[i:j] (indices clamped, empty range is a no-op)."""
        n = len(self)
        i = max(0, min(i, n))
        j = max(i, min(j, n))
        if i == j:
            return self
        left, mid_right = _split(self._root, i)
        _, right = _split(mid_right, j - i)
        self._root = _concat(left, right)
        return self


def _clamp(i: int, n: int) -> int:
    return max(0, min(i, n))


def _collect(t: _Node | None, lo: int, hi: int, out: list[str]) -> None:
    """Append t[lo:hi] fragments to out (0 <= lo <= hi <= t.length)."""
    if t is None or hi <= lo:
        return
    if t.text is not None:
        out.append(t.text[lo:hi])
        return
    if lo < t.left.length:
        _collect(t.left, lo, min(hi, t.left.length), out)
    if hi > t.left.length:
        _collect(
            t.right,
            max(0, lo - t.left.length),
            hi - t.left.length,
            out,
        )
"})
