result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/test_rope_stateful.py", "content": """"Hypothesis stateful test: mirror every rope operation against a plain
Python string model and verify str(rope) == model after every rule."""

from hypothesis import HealthCheck, invariant, settings
from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, initialize, rule

from rope import Rope


class RopeMachine(RuleBasedStateMachine):
    def __init__(self):
        super().__init__()
        self.rope = Rope()
        self.model = ""

    @initialize(s=st.text(max_size=120))
    def seed(self, s):
        self.model = s
        self.rope = Rope.from_str(s)

    def _position(self, data, lo=0):
        """Draw an index in [lo, len(model)] plus out-of-range noise."""
        span = len(self.model) - lo
        base = data.draw(st.integers(lo, lo + span)) if span >= 0 else lo
        noisy = data.draw(st.booleans())
        if noisy:
            base += data.draw(st.integers(min_value=-25, max_value=25))
        return base

    @rule(data=st.data(), s=st.text(max_size=70))
    def do_insert(self, data, s):
        i = self._position(data)
        self.rope.insert(i, s)
        self.model = self.model[:i] + s + self.model[i:]

    @rule(data=st.data())
    def do_delete(self, data):
        i = self._position(data)
        j = self._position(data, lo=min(i, len(self.model)))
        j = max(i, j)
        self.rope.delete(i, j)
        self.model = self.model[:i] + self.model[j:]

    @rule(data=st.data())
    def spot_check_index(self, data):
        if not self.model:
            return
        i = data.draw(st.integers(0, len(self.model) - 1))
        assert self.rope.index(i) == self.model[i]

    @rule(data=st.data())
    def spot_check_slice(self, data):
        n = len(self.model)
        a = data.draw(st.integers(-30, n + 30))
        b = data.draw(st.integers(-30, n + 30))
        assert self.rope.slice(a, b) == self.model[max(0, min(a, n)):max(a, min(b, n))]

    @rule()
    def check_len(self):
        assert len(self.rope) == len(self.model)

    @invariant()
    def rope_matches_model(self):
        assert str(self.rope) == self.model


RopeMachine.TestCase.settings = settings(
    max_examples=60,
    stateful_step_count=75,
    deadline=None,
    suppress_health_check=[HealthCheck.too_slow],
)

TestRopeMachine = RopeMachine.TestCase
"})
